scripts.code:
pm.request.headers.add({ key: "X-Added", value: "1" });
pm.request.headers.upsert({ key: "Accept", value: "text/plain" });
pm.request.headers.remove("X-Remove");
pm.request.addHeader({ key: "X-Signature", value: pm.variables.replaceIn("sig-{{user}}") });
pm.request.url.query.add({ key: "page", value: "2" });
pm.request.method = "post";
pm.request.body.update({ mode: "raw", raw: JSON.stringify({ user: pm.variables.get("user") }) });
console.log(pm.request.headers.get("accept"), pm.request.url.getQueryString(), pm.request.body.raw);
